  split; [lia|]. split; [| exact (gei_1RB1RB_1LC1RC_1RA0LD_0RC0LD p j q0 E)].
  rewrite (gsi_1RB1RB_1LC1RC_1RA0LD_0RC0LD p j q0 E).
  exact (srun_sound tm false true chi_1RB1RB_1LC1RC_1RA0LD_0RC0LD A0_1RB1RB_1LC1RC_1RA0LD_0RC0LD A1_1RB1RB_1LC1RC_1RA0LD_0RC0LD 6 6
