Lemma lbl_1RB1RB_1LC1RC_1RA0LD_0RC0LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_1LC1RC_1RA0LD_0RC0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_1LC1RC_1RA0LD_0RC0LD) = lift (Cc (Pos.succ p)).
