(** ** The lap *)

Lemma lap_1RB1RB_1LC1RC_1RA0LD_0RC0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RB_1LC1RC_1RA0LD_0RC0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC1RC_1RA0LD_0RC0LD B0_1RB1RB_1LC1RC_1RA0LD_0RC0LD B1_1RB1RB_1LC1RC_1RA0LD_0RC0LD 6 12 p j' [] []).
    + exact run_ovf_1RB1RB_1LC1RC_1RA0LD_0RC0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LC1RC_1RA0LD_0RC0LD p j' E).
    + exact (geo_1RB1RB_1LC1RC_1RA0LD_0RC0LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RB_1LC1RC_1RA0LD_0RC0LD : stepn tmm_1RB1RB_1LC1RC_1RA0LD_0RC0LD 10 InitES = Some (lift (Cc 1)).
