              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1RB_1LC1RC_1RA0LD_0RC0LD 10 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RB_1LC1RC_1RA0LD_0RC0LD : existsb (fun tg => cfires tmm_1RB1RB_1LC1RC_1RA0LD_0RC0LD c0 10 tg) pins_1RB1RB_1LC1RC_1RA0LD_0RC0LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LC1RC_1RA0LD_0RC0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RB_1LC1RC_1RA0LD_0RC0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_1LC1RC_1RA0LD_0RC0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_1LC1RC_1RA0LD_0RC0LD : forall t, ~ In t pins_1RB1RB_1LC1RC_1RA0LD_0RC0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_1LC1RC_1RA0LD_0RC0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD [SCycL 3 0; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD [SCycL 3 0; SWin 3; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD [SCycL 3 0; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD [SCycL 3 0; SWin 3; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD [SCycL 3 0; SWin 3; SWinL 7; SCycR 3; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RC_1RA0LD_0RC0LD [SCycL 3 0; SWin 3; SWinL 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_1RB1RB_1LC1RC_1RA0LD_0RC0LD : NonHalt tmm_1RB1RB_1LC1RC_1RA0LD_0RC0LD /\ QHBoundTr 32779478 tmm_1RB1RB_1LC1RC_1RA0LD_0RC0LD /\ QuasiHaltsTr tmm_1RB1RB_1LC1RC_1RA0LD_0RC0LD.
