  apply (lap_qh_stage tmm_1RB1RB_1LC1RC_1RA0LD_0RC0LD pins_1RB1RB_1LC1RC_1RA0LD_0RC0LD Cc 1 10 32779478).
  - exact bootq_1RB1RB_1LC1RC_1RA0LD_0RC0LD.
  - intros p _. apply lap_1RB1RB_1LC1RC_1RA0LD_0RC0LD.
  - intros t Ht p _. apply fire_1RB1RB_1LC1RC_1RA0LD_0RC0LD. exact Ht.
  - exact wit_1RB1RB_1LC1RC_1RA0LD_0RC0LD.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_1RB1RB_1LC1RC_1RA0LD_0RC0LD : NonHalt tm_1RB1RB_1LC1RC_1RA0LD_0RC0LD /\ QHBoundTr 32779478 tm_1RB1RB_1LC1RC_1RA0LD_0RC0LD /\ QuasiHaltsTr tm_1RB1RB_1LC1RC_1RA0LD_0RC0LD.
