Lemma fire_1RB1RB_1LC1RC_1RB0LD_0RA1LD : forall t, ~ In t pins_1RB1RB_1LC1RC_1RB0LD_0RA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
