      with (l := [SWin 3; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_1RC0RD_1LA0LC_1LC1RD
      with (l := [SWin 3; SCycL 1 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_1RC0RD_1LA0LC_1LC1RD
      with (l := [SWin 3]).
    vm_compute; reflexivity.
Qed.

