Lemma fire_1RB1RC_0LC0RB_1LA1LD_1RC1LC : forall t, ~ In t pins_1RB1RC_0LC0RB_1LA1LD_1RC1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
