(** 1RB1RC_1LB1RA_1LD1RB_0RC0LD *)
(** 1RB1RC_1LB1RA_1LD1RB_0RC0LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1RC_1LB1RA_1LD1RB_0RC0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DL StB | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S0 DR StC | StD, S1 => mk S0 DL StD end.

(** Its mirror 1LB1LC_1RB1LA_1RD1LB_0LC0RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RC_1LB1RA_1LD1RB_0RC0LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DR StB | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DL StC | StD, S1 => mk S0 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RC_1LB1RA_1LD1RB_0RC0LD : list Instr := [(StA, S0)].
Definition tmw_1RB1RC_1LB1RA_1LD1RB_0RC0LD : TM := tm_wrap_trs tmm_1RB1RC_1LB1RA_1LD1RB_0RC0LD pins_1RB1RC_1LB1RA_1LD1RB_0RC0LD.
Local Notation tm := tmw_1RB1RC_1LB1RA_1LD1RB_0RC0LD.

Lemma mirror_ok_1RB1RC_1LB1RA_1LD1RB_0RC0LD : mirror_tm tm_1RB1RC_1LB1RA_1LD1RB_0RC0LD = tmm_1RB1RC_1LB1RA_1LD1RB_0RC0LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

