  unfold Cc_1RB1RC_1LC1RD_0RB0LC_1RA0LA, cden, Z0_1RB1RC_1LC1RD_0RB0LC_1RA0LA, Z1_1RB1RC_1LC1RD_0RB0LC_1RA0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
