    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RC_1LC1RD_0RB0LC_1RA0LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 2]).
