  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (H1 & _).
  unfold Cc_1RB1RC_1LC1RD_0RB0LC_1RA0LD, cden, B0_1RB1RC_1LC1RD_0RB0LC_1RA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RC_1LC1RD_0RB0LC_1RA0LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RC_1LC1RD_0RB0LC_1RA0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RC_1LC1RD_0RB0LC_1RA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RC_1LC1RD_0RB0LC_1RA0LD
             = (StC, (rep [S0;S0;S0] (S j) ++ [S1], S0, [S1;S1;S1]))).
  { unfold cden, B1_1RB1RC_1LC1RD_0RB0LC_1RA0LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0;S0] (S j) ++ [S1]) ++ [S0], S0, [S1;S1;S1]))).
  { unfold Cc_1RB1RC_1LC1RD_0RB0LC_1RA0LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RC_1LC1RD_0RB0LC_1RA0LD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RC_1LC1RD_0RB0LC_1RA0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RC_1LC1RD_0RB0LC_1RA0LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RC_1LC1RD_0RB0LC_1RA0LD B0_1RB1RC_1LC1RD_0RB0LC_1RA0LD B1_1RB1RC_1LC1RD_0RB0LC_1RA0LD 6 8 p j' [] []).
    + exact run_ovf_1RB1RC_1LC1RD_0RB0LC_1RA0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RC_1LC1RD_0RB0LC_1RA0LD p j' E).
    + exact (geo_1RB1RC_1LC1RD_0RB0LC_1RA0LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RC_1LC1RD_0RB0LC_1RA0LD : stepn tmm_1RB1RC_1LC1RD_0RB0LC_1RA0LD 22 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB1RC_1LC1RD_0RB0LC_1RA0LD 22 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1RC_1LC1RD_0RB0LC_1RA0LD 22 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
