  apply (lap_qh_stage tmm_1RB1RC_1LC1RD_0RB0LC_1RA0LD pins_1RB1RC_1LC1RD_0RB0LC_1RA0LD Cc 1 22 32779478).
  - exact bootq_1RB1RC_1LC1RD_0RB0LC_1RA0LD.
  - intros p _. apply lap_1RB1RC_1LC1RD_0RB0LC_1RA0LD.
  - intros t Ht p _. apply fire_1RB1RC_1LC1RD_0RB0LC_1RA0LD. exact Ht.
  - exact wit_1RB1RC_1LC1RD_0RB0LC_1RA0LD.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_1RB1RC_1LC1RD_0RB0LC_1RA0LD : NonHalt tm_1RB1RC_1LC1RD_0RB0LC_1RA0LD /\ QHBoundTr 32779478 tm_1RB1RC_1LC1RD_0RB0LC_1RA0LD /\ QuasiHaltsTr tm_1RB1RC_1LC1RD_0RB0LC_1RA0LD.
