  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S1] (S j) ++ [S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_1RB1RC_1RC0LD_1LD1RB_0RA1LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
