  apply (lap_qh_stage tmm_1RB1RC_1RC0LD_1LD1RB_0RA1LD pins_1RB1RC_1RC0LD_1LD1RB_0RA1LD Cc 1 28 32779478).
  - exact bootq_1RB1RC_1RC0LD_1LD1RB_0RA1LD.
